public class Test {
    public static void main(String[] a) {
        UserService s = new UserService();
        String reg = capture(() -> s.register("bob"));
        String del = capture(() -> s.delete("bob"));
        String missing = capture(() -> s.delete("zed"));
        if (!(reg.trim().isEmpty())) throw new AssertionError("register should not log");
        if (!(del.contains("Deleted user bob"))) throw new AssertionError("delete not logged");
        if (!(!missing.contains("Deleted user"))) throw new AssertionError("logged a delete that did not happen");
        if (!(s.count() == 0)) throw new AssertionError("behavior changed");
        System.out.println("PASS");
    }

    static String capture(Runnable r) {
        java.io.PrintStream original = System.out;
        java.io.ByteArrayOutputStream buf = new java.io.ByteArrayOutputStream();
        System.setOut(new java.io.PrintStream(buf, true));
        try { r.run(); } finally { System.setOut(original); }
        return buf.toString();
    }
}
